        len += blob_len(self.chapter.len(), EVENT_BOOK_FINISHED_CHAPTER_MAX_BYTES)?;
        len += 4;
        if bits & 0x01 != 0 {
            len += 4;
        }
        if bits & 0x02 != 0 {
            len += 4;
        }
        if bits & 0x04 != 0 {
            len += 4;
        }
